            return solve(o,x,0,mask);
        }
        auto key=make_tuple(o,x,turn,mask);
        auto it=memo.find(key); if(it!=memo.end()) return it->second;
        long long best=LLONG_MAX;
        for(int d=1;d<=4;d++){int c=x+d; if(c<=n && !((mask>>c)&1)){ best=min(best, -a[c]+solve(o,c,0,mask|(1<<c)));}}
