#include<bits/stdc++.h>
using namespace std;
int n; long long a[40];
map<tuple<int,int,int,int>,long long> memo;
// store chosen move
map<tuple<int,int,int,int>,int> mv;

long long solve(int o,int x,int turn,int mask){
    if(turn==0){
        int any=0;
        for(int d=1;d<=4;d++){int c=o+d; if(c<=n && !((mask>>c)&1)) any=1;}
        if(!any){
            int anyx=0;
            for(int d=1;d<=4;d++){int c=x+d; if(c<=n && !((mask>>c)&1)) anyx=1;}
            if(!anyx) return 0;
            return solve(o,x,1,mask);
        }
        auto key=make_tuple(o,x,turn,mask);
        auto it=memo.find(key); if(it!=memo.end()) return it->second;
        long long best=LLONG_MIN; int bd=-1;
        for(int d=1;d<=4;d++){int c=o+d; if(c<=n && !((mask>>c)&1)){ long long v=a[c]+solve(c,x,1,mask|(1<<c)); if(v>best){best=v;bd=c;}}}
        memo[key]=best; mv[key]=bd; return best;
    } else {
        int any=0;
        for(int d=1;d<=4;d++){int c=x+d; if(c<=n && !((mask>>c)&1)) any=1;}
        if(!any){
            int anyo=0; for(int d=1;d<=4;d++){int c=o+d; if(c<=n && !((mask>>c)&1)) anyo=1;}
            if(!anyo) return 0;
            return solve(o,x,0,mask);
        }
        auto key=make_tuple(o,x,turn,mask);
        auto it=memo.find(key); if(it!=memo.end()) return it->second;
        long long best=LLONG_MAX; int bd=-1;
        for(int d=1;d<=4;d++){int c=x+d; if(c<=n && !((mask>>c)&1)){ long long v=-a[c]+solve(o,c,0,mask|(1<<c)); if(v<best){best=v;bd=c;}}}
        memo[key]=best; mv[key]=bd; return best;
    }
}
void run(int N,vector<long long> arr){
    n=N; for(int i=0;i<(int)arr.size();i++) a[i]=arr[i];
    memo.clear(); mv.clear();
    int mask=(1<<1)|(1<<2);
    long long val=solve(1,2,0,mask);
    // reconstruct
    int o=1,x=2,turn=0,msk=mask;
    cout<<"val="<<val<<" moves:";
    while(true){
        if(turn==0){
            int any=0; for(int d=1;d<=4;d++){int c=o+d; if(c<=n&&!((msk>>c)&1))any=1;}
            if(!any){ int ax=0; for(int d=1;d<=4;d++){int c=x+d;if(c<=n&&!((msk>>c)&1))ax=1;} if(!ax)break; turn=1; continue;}
            auto key=make_tuple(o,x,turn,msk);
            if(!mv.count(key))break;
            int c=mv[key]; cout<<" O"<<o<<"->"<<c; o=c; msk|=(1<<c); turn=1;
        } else {
            int any=0; for(int d=1;d<=4;d++){int c=x+d; if(c<=n&&!((msk>>c)&1))any=1;}
            if(!any){ int ao=0; for(int d=1;d<=4;d++){int c=o+d;if(c<=n&&!((msk>>c)&1))ao=1;} if(!ao)break; turn=0; continue;}
            auto key=make_tuple(o,x,turn,msk);
            if(!mv.count(key))break;
            int c=mv[key]; cout<<" X"<<x<<"->"<<c; x=c; msk|=(1<<c); turn=0;
        }
    }
    cout<<"  final O="<<o<<" X="<<x<<" free:";
    for(int i=1;i<=n;i++) if(!((msk>>i)&1)) cout<<i<<" ";
    cout<<"\n";
}
