    srand(12345);
    for(int t=0;t<8;t++){
        int N=10+rand()%3;
        vector<long long> arr(N+1,0);
        for(int i=3;i<=N;i++) arr[i]=1+rand()%9;
        cout<<"n="<<N<<" a="; for(int i=3;i<=N;i++)cout<<arr[i]<<" "; cout<<"\n";
        run(N,arr);
    }
    return 0;
}

