// min over optimal lines of max gap
long long bestGap;
void dfs(int o,int x,int turn,int mask,int curGap){
    if(curGap>=bestGap) return;
    // check terminal
    int anyo=0,anyx=0;
    for(int d=1;d<=4;d++){int c=o+d;if(c<=n&&!((mask>>c)&1))anyo=1;}
    for(int d=1;d<=4;d++){int c=x+d;if(c<=n&&!((mask>>c)&1))anyx=1;}
    if(!anyo&&!anyx){bestGap=min(bestGap,(long long)curGap);return;}
    long long v=solve(o,x,turn,mask);
    if(turn==0){
        if(!anyo){dfs(o,x,1,mask,curGap);return;}
        for(int d=1;d<=4;d++){int c=o+d;if(c<=n&&!((mask>>c)&1)){ if(a[c]+solve(c,x,1,mask|(1<<c))==v){ int ng=max(curGap,abs(c-x)); dfs(c,x,1,mask|(1<<c),ng);} }}
    } else {
        if(!anyx){dfs(o,x,0,mask,curGap);return;}
        for(int d=1;d<=4;d++){int c=x+d;if(c<=n&&!((mask>>c)&1)){ if(-a[c]+solve(o,c,0,mask|(1<<c))==v){ int ng=max(curGap,abs(o-c)); dfs(o,c,0,mask|(1<<c),ng);} }}
    }
}
int main(){
    // exhaustive binary arrays for n=9..12, find worst min-max gap
    for(int N=9;N<=12;N++){
        int m=N-2; long long worst=0; vector<long long> warr;
        for(int b=0;b<(1<<m);b++){
            vector<long long> v(N+1,0);
            for(int j=0;j<m;j++) v[3+j]=(b>>j)&1;
            run(N,v);
            bestGap=100;
            dfs(1,2,0,(1<<1)|(1<<2),1);
            if(bestGap>worst){worst=bestGap;warr=v;}
        }
        cout<<"N="<<N<<" worst min-max gap="<<worst<<" array:"; for(int i=3;i<=N;i++)cout<<warr[i]<<" "; cout<<"\n";
    }
    return 0;
}

