long long greedy(int N,vector<long long> arr){
    vector<int> occ(N+1,0); occ[1]=occ[2]=1; int o=1,x=2,turn=0; long long diff=0;
    while(true){
        int anyo=0,anyx=0;
        for(int d=1;d<=4;d++){int c=o+d;if(c<=N&&!occ[c])anyo=1;}
        for(int d=1;d<=4;d++){int c=x+d;if(c<=N&&!occ[c])anyx=1;}
