long long solve(int o,int x,int turn,int mask){
    if(turn==0){
        int any=0; for(int d=1;d<=4;d++){int c=o+d; if(c<=n && !((mask>>c)&1)) any=1;}
        if(!any){int anyx=0;for(int d=1;d<=4;d++){int c=x+d; if(c<=n && !((mask>>c)&1)) anyx=1;} if(!anyx)return 0; return solve(o,x,1,mask);}
        auto key=make_tuple(o,x,turn,mask); auto it=memo.find(key); if(it!=memo.end())return it->second;
        long long best=LLONG_MIN;
        for(int d=1;d<=4;d++){int c=o+d; if(c<=n && !((mask>>c)&1)){best=max(best,a[c]+solve(c,x,1,mask|(1<<c)));}}
        memo[key]=best;return best;
    } else {
        int any=0;for(int d=1;d<=4;d++){int c=x+d; if(c<=n && !((mask>>c)&1)) any=1;}
        if(!any){int anyo=0;for(int d=1;d<=4;d++){int c=o+d; if(c<=n && !((mask>>c)&1)) anyo=1;} if(!anyo)return 0; return solve(o,x,0,mask);}
        auto key=make_tuple(o,x,turn,mask);auto it=memo.find(key);if(it!=memo.end())return it->second;
        long long best=LLONG_MAX;
        for(int d=1;d<=4;d++){int c=x+d; if(c<=n && !((mask>>c)&1)){best=min(best,-a[c]+solve(o,c,0,mask|(1<<c)));}}
        memo[key]=best;return best;
