long long sp[40];
long long single(int p){ // max score from p alone, all free
    if(p>=n-3) {} 
    if(sp[p]!=-1) return sp[p];
    long long best=0; bool any=false;
    for(int d=1;d<=4;d++){int c=p+d; if(c<=n){any=true;best=max(best,a[c]+single(c));}}
    return sp[p]= any?best:0;
}
int main(){
    srand(31); 
    for(int t=0;t<40;t++){
        int N=10+rand()%5; n=N;
        vector<long long> v(N+1,0); for(int i=3;i<=N;i++)v[i]=1+rand()%1000;
        for(int i=0;i<=N;i++)a[i]=v[i];
        memo.clear(); for(int i=0;i<=N;i++)sp[i]=-1;
        solve(1,2,0,(1<<1)|(1<<2));
        // compare for states with gap>=G
        for(auto&kv:memo){}
        // iterate states in memo with turn and mask, compute sp difference; also need sp for arbitrary p
        int checked=0,match=0;
        for(auto&kv:memo){
            int o=get<0>(kv.first),x=get<1>(kv.first),turn=get<2>(kv.first),mask=get<3>(kv.first);
            if(abs(o-x)>=9){
                long long full=kv.second;
                // compute independent: leader sp - trailer sp (sign by turn? value is from O's perspective)
                long long spO=0,spX=0;
                // single from o for O, from x for X
                for(int i=0;i<=N;i++)sp[i]=-1;
                spO=single(o); spX=single(x);
                long long indep=spO-spX;
                checked++; if(indep==full)match++;
            }
        }
        if(checked)cout<<"N="<<N<<" states gap>=9 checked="<<checked<<" match="<<match<<"\n";
    }
    return 0;
}

